<script>
(function(){let timer,req;function search(keyword){clearTimeout(timer);if(keyword.trim().length<2){$('.search-result').empty();return}timer=setTimeout(function(){if(req)req.abort();req=$.get('{{ route('livesearch') }}',{keyword:keyword.trim()},function(html){$('.search-result').html(html)})},260)}$('.desktop-search,.mobile-search-input').on('input',function(){search($(this).val())});$('#mobile-search-focus,#mobile-search-focus-bottom').on('click',function(e){e.preventDefault();$('.mobile-search-input').focus();window.scrollTo({top:0,behavior:'smooth'})});function token(){return $('meta[name="csrf-token"]').attr('content')}function refreshCount(){$.get('{{ route('cart.count') }}',function(html){const number=$('<div>').html(html).find('.margin-shopping span').first().text();if(number)$('.js-cart-count').text(number)})}$(document).on('click','.cart_remove',function(e){e.preventDefault();$.post('{{ route('cart.remove') }}',{id:$(this).data('id'),_token:token()},function(){location.reload()})})();
</script>
